const log = document.getElementById('log');

// minDate and maxDate take YYYY-MM-DD strings, so a range can move with today.
function isoDate(date) {
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${date.getFullYear()}-${month}-${day}`;
}

const today = new Date();
const lastDay = new Date(today);
lastDay.setDate(today.getDate() + 30);

const appointment = document.getElementById('appointment-date');
appointment.minDate = isoDate(today);
appointment.maxDate = isoDate(lastDay);

// The incident already happened, so the calendar stops at today and opens
// on the month before.
const monthAgo = new Date(today);
monthAgo.setMonth(today.getMonth() - 1);
const incident = document.getElementById('incident-date');
incident.maxDate = isoDate(today);
incident.startDate = isoDate(monthAgo);

// nys-change reports a YYYY-MM-DD string, or an empty string after Clear.
document.querySelectorAll('nys-datepicker').forEach((picker) => {
  picker.addEventListener('nys-change', (e) => {
    log.textContent = `${picker.label}: ${e.detail.value || '(cleared)'}`;
  });
});
